"""Load standard items and spell descriptions for UI tooltips/lists."""

from __future__ import annotations

import json
from functools import lru_cache

import paths

DATA = paths.bundle_dir() / "data"


@lru_cache(maxsize=1)
def load_standard_items() -> list[dict]:
    """Full list including armour (kept for later / reference)."""
    path = DATA / "standard_items.json"
    if not path.is_file():
        return []
    items = json.loads(path.read_text(encoding="utf-8"))
    for it in items:
        it.setdefault("slot_cost", 1)
        it.setdefault("kind", "simple")
        it.setdefault("spellcaster_allowed", True)
    return items


def load_spellcaster_items() -> list[dict]:
    """Items shown on wizard/apprentice slots (no armour/shield; unarmed not listed)."""
    return [it for it in load_standard_items() if it.get("spellcaster_allowed", True)]


@lru_cache(maxsize=1)
def load_potion_choices() -> list[str]:
    path = DATA / "potions.json"
    if path.is_file():
        return json.loads(path.read_text(encoding="utf-8"))
    return []


@lru_cache(maxsize=1)
def load_potion_descriptions() -> dict[str, str]:
    path = DATA / "potion_descriptions.json"
    if not path.is_file():
        return {}
    return json.loads(path.read_text(encoding="utf-8"))


def load_potion_choices_detailed() -> list[dict]:
    """Potions with a derived category label and rules description, for the reference page."""
    descs = load_potion_descriptions()
    out = []
    for name in load_potion_choices():
        kind = name.split(" of ")[0] if " of " in name else name.split()[-1]
        out.append({
            "name": name,
            "kind": kind,
            "description": descs.get(name, "") or "No description available.",
        })
    return out


@lru_cache(maxsize=1)
def load_bestiary() -> list[dict]:
    path = DATA / "bestiary.json"
    if not path.is_file():
        return []
    return json.loads(path.read_text(encoding="utf-8"))


@lru_cache(maxsize=1)
def load_spell_names() -> list[str]:
    try:
        from frostgrave_data import SPELLS

        names = [sp["name"] for _, sps in SPELLS.items() for sp in sps]
        return sorted(set(names), key=str.lower)
    except Exception:
        return []


@lru_cache(maxsize=1)
def load_spell_descriptions() -> dict[str, str]:
    path = DATA / "spell_descriptions.json"
    if not path.is_file():
        return {}
    return json.loads(path.read_text(encoding="utf-8"))


def spell_description(name: str) -> str:
    return load_spell_descriptions().get(name, "") or "No description available."


def enrich_spells_with_descriptions(spells: list[dict]) -> list[dict]:
    descs = load_spell_descriptions()
    out = []
    for sp in spells:
        row = dict(sp)
        row["description"] = descs.get(sp.get("name", ""), "") or "No description available."
        out.append(row)
    return out


def equipment_bonuses(slots: list) -> dict:
    """Sum the Armour/Move bonuses granted by known Armour-category items (Shield,
    Light Armour, Heavy Armour) sitting in these item slots. Matches by exact
    catalog name (case-insensitive), same idiom as item_slot_cost() below."""
    bonus = {"armour": 0, "move": 0}
    for raw in slots or []:
        name = (raw or "").strip().lower()
        if not name:
            continue
        for it in load_standard_items():
            if it["name"].lower() == name:
                bonus["armour"] += int(it.get("armour_bonus", 0))
                bonus["move"] -= int(it.get("move_penalty", 0))
                break
    return bonus


def item_slot_cost(name: str) -> int:
    """How many item slots this equipment uses (default 1)."""
    n = (name or "").strip().lower()
    if not n:
        return 1
    for it in load_standard_items():
        if it["name"].lower() == n:
            return int(it.get("slot_cost", 1))
    if any(k in n for k in ("two-handed", "two handed", "2h ", "2-handed", "2 handed")):
        return 2
    return 1


def parse_item_selection(value: str) -> tuple[str, str]:
    """
    Map a stored slot value to (main_pick, detail_value).
    main_pick is the primary dropdown value (Potion/Scroll/Grimoire/Hand Weapon/...).
    detail_value is potion name or spell name for the secondary dropdown, or '' for free text.
    """
    v = (value or "").strip()
    if not v:
        return "", ""

    # Exact main item (simple arms etc.)
    for it in load_standard_items():
        if it["name"] == v and it.get("kind", "simple") == "simple":
            return v, ""

    potions = load_potion_choices()
    if v in potions or v.lower().startswith("potion of ") or v in {
        "Poison",
        "Explosive Cocktail",
        "Construct Oil",
        "Elixir of Speed",
        "Elixir of the Chameleon",
        "Elixir of Life",
        "Cordial of Clearsight",
        "Cordial of Empowerment",
        "Philtre of Fury",
        "Philtre of Fairy Dust",
        "Bottle of Burrowing",
        "Bottle of Darkness",
        "Bottle of Dreams and Nightmares",
        "Bottle of Null",
        "Ethereal Vacuum",
        "Shatterstar Draught",
        "Shrinking Potion",
    }:
        return "Potion", v

    if v.startswith("Scroll of "):
        return "Scroll", v[len("Scroll of ") :]
    if v == "Scroll":
        return "Scroll", ""

    if v.startswith("Grimoire of "):
        return "Grimoire", v[len("Grimoire of ") :]
    if v == "Grimoire":
        return "Grimoire", ""

    # Known simple name
    for it in load_standard_items():
        if it["name"] == v:
            return v, ""

    # Free-text / vault custom
    return "", v

files.templates/_item_slots.html:
{#
  Item slot editor with short primary list + secondary detail for Potion/Scroll/Grimoire.
  Expects: prefix, n, slots, standard_items, vault_names, potion_choices, spell_names
#}
{% set vault_names = vault_names or [] %}
{% set potion_choices = potion_choices or [] %}
{% set spell_names = spell_names or [] %}
{% set cat_order = ['Weapon', 'Missile', 'Armour', 'Gear', 'Consumable'] %}

{# JSON blobs for JS #}
<script type="application/json" id="{{ prefix }}-potion-data">{{ potion_choices|tojson }}</script>
<script type="application/json" id="{{ prefix }}-spell-data">{{ spell_names|tojson }}</script>

<div class="item-slots" data-prefix="{{ prefix }}" data-count="{{ n }}">
  {% for i in range(n) %}
    {% set cur = slots[i] if slots|length > i else '' %}
    <div class="form-row item-slot-row" data-index="{{ i }}">
      <label>Slot {{ i + 1 }}</label>
      <div class="item-slot-controls">
        <select
          class="item-slot-pick"
          data-index="{{ i }}"
          aria-label="Item type for slot {{ i + 1 }}"
        >
          <option value="">— empty / custom —</option>
          {% for cat in cat_order %}
            {% set group = standard_items|selectattr('category', 'equalto', cat)|list %}
            {% if group %}
              <optgroup label="{{ cat }}">
                {% for it in group %}
                  {% set sc = it.slot_cost if it.slot_cost is defined else 1 %}
                  {% set kind = it.kind if it.kind is defined else 'simple' %}
                  <option
                    value="{{ it.name }}"
                    data-slots="{{ sc }}"
                    data-kind="{{ kind }}"
                  >
                    {{ it.name }}{% if sc > 1 %} ({{ sc }} slots){% endif %}
                  </option>
                {% endfor %}
              </optgroup>
            {% endif %}
          {% endfor %}
          {% if vault_names %}
            <optgroup label="Vault / recorded loot">
              {% for name in vault_names %}
                <option value="{{ name }}" data-slots="1" data-kind="vault">
                  {{ name }}
                </option>
              {% endfor %}
            </optgroup>
          {% endif %}
        </select>

        {# Secondary: type-specific dropdown OR free text (one visible at a time) #}
        <select
          class="item-slot-detail"
          data-index="{{ i }}"
          aria-label="Specific type for slot {{ i + 1 }}"
          hidden
        >
          <option value="">— choose type —</option>
        </select>
        <input
          id="{{ prefix }}_slot_{{ i }}"
          class="item-slot-text"
          name="{{ prefix }}_slot_{{ i }}"
          type="text"
          value="{{ cur }}"
          placeholder="___ or custom item"
          data-index="{{ i }}"
          list="{{ prefix }}_item_suggestions"
        />
      </div>
    </div>
  {% endfor %}
  <datalist id="{{ prefix }}_item_suggestions">
    {% for it in standard_items if it.kind == 'simple' %}
      <option value="{{ it.name }}"></option>
    {% endfor %}
    {% for name in potion_choices %}
      <option value="{{ name }}"></option>
    {% endfor %}
    {% for name in spell_names %}
      <option value="Scroll of {{ name }}"></option>
      <option value="Grimoire of {{ name }}"></option>
    {% endfor %}
    {% for name in vault_names %}
      <option value="{{ name }}"></option>
    {% endfor %}
  </datalist>
</div>

files.templates/settings.html:
{% extends "base.html" %}
{% block title %}Settings · Frostgrave{% endblock %}
{% block content %}
  <section class="hero">
    <h1>Settings</h1>
    <p>Choose where warbands and portraits are saved on this PC.</p>
  </section>

  <div class="card">
    <h2>Data folder</h2>
    <p class="muted">
      Currently using: <code>{{ active_dir }}</code>
    </p>
    {% if configured_dir != active_dir %}
      <p class="flash success" style="display:block">
        Configured folder is <code>{{ configured_dir }}</code> — restart the app for this to take effect.
      </p>
    {% endif %}
    <form method="post" action="{{ url_for('settings') }}">
      <div class="form-row inline">
        <div style="flex:1">
          <label for="data_dir">Folder path</label>
          <input id="data_dir" name="data_dir" type="text" value="{{ configured_dir }}" style="width:100%" />
        </div>
        <div>
          <label>&nbsp;</label>
          <button type="button" class="btn secondary" id="browse-btn">Browse…</button>
        </div>
        <div>
          <label>&nbsp;</label>
          <button class="btn" type="submit">Save</button>
        </div>
      </div>
    </form>
    <p class="muted" style="font-size:0.85rem;margin-top:0.5rem">
      Default: <code>{{ default_dir }}</code>. Changes take effect after restarting the app — warbands
      already in the old folder are left where they are (they are not moved automatically).
    </p>
  </div>

  <script>
    (function () {
      const btn = document.getElementById('browse-btn');
      const input = document.getElementById('data_dir');
      if (!btn) return;
      btn.addEventListener('click', function () {
        btn.disabled = true;
        const original = btn.textContent;
        btn.textContent = 'Waiting for folder picker…';
        fetch("{{ url_for('settings_browse') }}", { method: 'POST' })
          .then((r) => r.json())
          .then((data) => {
            if (data.path) input.value = data.path;
          })
          .catch(() => {})
          .finally(() => {
            btn.disabled = false;
            btn.textContent = original;
          });
      });
    })();
  </script>
{% endblock %}

