  font-size: 0.88em;
  background: var(--bg);
  padding: 0.1rem 0.35rem;
  border-radius: 4px;
  border: 1px solid var(--border);
}

.section-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-top: 0.75rem;
}

/* Portraits */
.portrait-sm {
  width: 40px;
  height: 40px;
  object-fit: cover;
  border-radius: 8px;
  border: 1px solid var(--border);
  background: var(--bg);
}

.portrait-md {
  width: 88px;
  height: 88px;
  object-fit: cover;
  border-radius: 10px;
  border: 1px solid var(--border);
  background: var(--bg);
  flex-shrink: 0;
}

.portrait-lg {
  width: 96px;
  height: 96px;
  object-fit: cover;
  border-radius: 12px;
  border: 1px solid var(--border);
  background: var(--bg);
  flex-shrink: 0;
}

.portrait-placeholder {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border-radius: 8px;
  border: 1px dashed var(--border);
  color: var(--muted);
  font-size: 0.85rem;
  background: var(--bg);
  object-fit: cover;
  flex-shrink: 0;
}

.portrait-sm,
.portrait-md,
.portrait-lg {
  object-fit: cover;
  object-position: center;
}

.portrait-md-ph {
  width: 88px;
  height: 88px;
  border-radius: 10px;
  font-size: 1.5rem;
}

.hero-with-portrait {
  display: flex;
  gap: 1.1rem;
  align-items: flex-start;
}

.warband-row {
  display: flex;
  gap: 0.75rem;
  align-items: center;
}

.warband-list-item {
  display: flex;
  align-items: stretch;
  gap: 0.5rem;
}

.warband-list-item .card-link {
  flex: 1;
  min-width: 0;
}

.warband-delete-form {
